import { after } from 'next/server'
import { revalidateTag } from 'next/cache'
import { getProducts, syncCatalogFromERP } from '@/lib/db'

export const metadata = {
  title: 'Product Catalog · Admin',
}

// Give the background ERP/PIM sync (thousands of SKUs) room to finish after the
// response has been sent to the admin.
export const maxDuration = 60

export default async function CatalogPage() {
  const products = await getProducts()

  // Inline Server Action. The regular HTML <form> below posts to it.
  async function syncCatalog() {
    'use server'
    // Defer the expensive ERP/PIM pull so the admin can keep working right
    // away. The catalog stays briefly stale, then is refreshed in the
    // background across every view tagged "products" (stale-while-revalidate).
    after(async () => {
      await syncCatalogFromERP()
      revalidateTag('products', 'max')
    })
  }

  return (
    <main
      style={{
        fontFamily: 'system-ui, sans-serif',
        maxWidth: 900,
        margin: '0 auto',
        padding: 24,
      }}
    >
      <header
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          gap: 16,
        }}
      >
        <h1 style={{ margin: 0 }}>Product Catalog</h1>
        <form action={syncCatalog}>
          <button type="submit">Sync latest catalog</button>
        </form>
      </header>

      <p style={{ color: '#666' }}>
        Cached for fast day-to-day browsing. Syncing pulls the latest pricing,
        inventory, and availability from the ERP/PIM in the background — your
        list may stay briefly stale, then update shortly after across all
        catalog views.
      </p>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr>
            <th style={cell}>ID</th>
            <th style={cell}>Name</th>
            <th style={cell}>Price</th>
            <th style={cell}>Availability</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td style={cell}>{product.id}</td>
              <td style={cell}>{product.name}</td>
              <td style={cell}>${product.price}</td>
              <td style={cell}>
                {product.inStock ? 'In stock' : 'Out of stock'}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

const cell = {
  border: '1px solid #ddd',
  padding: '8px 12px',
  textAlign: 'left',
} as const

