import { cacheLife, cacheTag } from 'next/cache'

export type Product = {
  id: number
  name: string
  price: number
  inStock: boolean
}

// In-memory store standing in for the product database / search index that the
// ERP/PIM sync writes to. Kept mutable so the background sync can update
// pricing, inventory, and availability. In production this would be your
// real database or search index, shared across instances.
let products: Product[] = [
  { id: 1, name: 'Laptop', price: 999, inStock: true },
  { id: 2, name: 'Phone', price: 699, inStock: true },
  { id: 3, name: 'Tablet', price: 499, inStock: false },
  { id: 4, name: 'Headphones', price: 199, inStock: true },
  { id: 5, name: 'Watch', price: 299, inStock: true },
]

// Simulated database read.
export async function getAllProducts(): Promise<Product[]> {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return products
}

// Cached catalog read. Tagged "products" so a single revalidateTag("products")
// refreshes every view that depends on the same catalog data. The catalog is
// read-heavy, so it is cached aggressively and only invalidated on-demand by
// the admin sync — day-to-day browsing never re-queries the underlying store.
export async function getProducts(): Promise<Product[]> {
  'use cache'
  cacheTag('products')
  cacheLife('max')
  return getAllProducts()
}

// Pull the latest catalog (pricing, inventory, availability) from the upstream
// ERP/PIM. This is the expensive part — it can touch thousands of SKUs — so it
// is designed to run in the background (via `after`), not on the request path.
export async function syncCatalogFromERP(): Promise<void> {
  // Simulate a slow upstream sync over thousands of SKUs.
  await new Promise((resolve) => setTimeout(resolve, 3000))

  products = [
    { id: 1, name: 'Laptop', price: 949, inStock: true },
    { id: 2, name: 'Phone', price: 649, inStock: true },
    { id: 3, name: 'Tablet', price: 469, inStock: true },
    { id: 4, name: 'Headphones', price: 179, inStock: true },
    { id: 5, name: 'Watch', price: 279, inStock: false },
    { id: 6, name: 'Keyboard', price: 129, inStock: true },
  ]
}

